"use client";

/**
 * Screenshot wall: a tilted wall of screens drifts slowly on the diagonal, then
 * one screen lifts forward to the centre with a caption under it.
 *
 * Written by Better Design. Painted from the theme prop; with no screenshots
 * each card shows a placeholder interface drawn from the same tokens.
 */
import { loadFont } from "@remotion/google-fonts/Inter";
import { AbsoluteFill, Img, interpolate, random, useCurrentFrame } from "remotion";
import { easings, pickFont, type VideoTheme, useVideoTheme, withAlpha } from "@/lib/bd-video";

const { fontFamily: INTER } = loadFont("normal", { weights: ["500", "600", "700"], subsets: ["latin"] });

const DURATION = 150;
const LIFT_AT = 82;
const LIFT_FRAMES = 34;
const COLS = 6;
const ROWS = 5;
const CARD_W = 480;
const CARD_H = 300;
const GAP = 40;
const TILT_X = 34;
const TILT_Z = -18;

export interface ScreenshotWallProps {
  /** Image URLs or static files, reused in order across the wall. Placeholders are drawn when empty. */
  screenshots?: string[];
  /** One line under the screen that lifts forward. */
  caption?: string;
  /** Which screenshot lifts forward, as an index into `screenshots`. */
  heroIndex?: number;
  theme?: Partial<VideoTheme>;
  /** A CSS font family the project has loaded. Defaults to the theme's face, then Inter. */
  font?: string;
}

const clamp = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;

/** One of four placeholder layouts, picked by the card's index. */
function PlaceholderScreen({ theme, seed }: { theme: VideoTheme; seed: number }) {
  const bar = (w: string, h: number, c = withAlpha(theme.foreground, 0.12)) => (
    <div style={{ width: w, height: h, borderRadius: h / 2, background: c, flexShrink: 0 }} />
  );
  const kind = seed % 4;
  const accent = random(`wall-accent-${seed}`) > 0.5;
  return (
    <div style={{ position: "absolute", inset: 0, padding: 26, display: "flex", flexDirection: "column", gap: 16, background: theme.card }}>
      <div style={{ display: "flex", gap: 8, alignItems: "center" }}>
        {[0, 1, 2].map((i) => (
          <div key={i} style={{ width: 10, height: 10, borderRadius: 5, background: withAlpha(theme.foreground, 0.16) }} />
        ))}
        <div style={{ flex: 1 }} />
        {bar("22%", 10)}
      </div>
      {kind === 0 && (
        <div style={{ flex: 1, display: "flex", alignItems: "flex-end", gap: 10 }}>
          {Array.from({ length: 9 }, (_, i) => (
            <div key={i} style={{ flex: 1, height: `${25 + random(`wall-${seed}-${i}`) * 70}%`, borderRadius: 6, background: i === 6 ? theme.primary : withAlpha(theme.primary, 0.22) }} />
          ))}
        </div>
      )}
      {kind === 1 &&
        [0.7, 0.5, 0.62, 0.44].map((w, i) => (
          <div key={i} style={{ display: "flex", gap: 14, alignItems: "center" }}>
            <div style={{ width: 34, height: 34, borderRadius: 17, background: i === 0 && accent ? withAlpha(theme.primary, 0.3) : theme.muted, flexShrink: 0 }} />
            {bar(`${w * 100}%`, 12, withAlpha(theme.foreground, 0.22))}
          </div>
        ))}
      {kind === 2 && (
        <>
          <div style={{ height: 110, borderRadius: 14, background: accent ? withAlpha(theme.primary, 0.2) : theme.muted }} />
          {bar("80%", 14, withAlpha(theme.foreground, 0.6))}
          {bar("64%", 10)}
          {bar("70%", 10)}
        </>
      )}
      {kind === 3 && (
        <>
          {bar("46%", 16, withAlpha(theme.foreground, 0.6))}
          {[0, 1].map((i) => (
            <div key={i} style={{ height: 40, borderRadius: 10, border: `1.5px solid ${theme.border}`, background: theme.background }} />
          ))}
          <div style={{ width: "40%", height: 40, borderRadius: 20, background: theme.primary }} />
        </>
      )}
    </div>
  );
}

/** A slow tilted wall of screens, with one lifting forward at the end. */
export function ScreenshotWall({
  screenshots = [],
  caption = "Every screen, one system.",
  heroIndex = 0,
  theme: themeOverride,
  font,
}: ScreenshotWallProps) {
  const theme = useVideoTheme(themeOverride);
  const frame = useCurrentFrame();
  const family = pickFont(font, theme, INTER);

  const drift = easings.inOut(interpolate(frame, [0, DURATION], [0, 1], clamp));
  const dx = interpolate(drift, [0, 1], [-220, 220]);
  const dy = interpolate(drift, [0, 1], [-140, 140]);
  const enter = easings.out(interpolate(frame, [0, 24], [0, 1], clamp));
  const lift = easings.out(interpolate(frame, [LIFT_AT, LIFT_AT + LIFT_FRAMES], [0, 1], clamp));
  const captionT = easings.out(interpolate(frame, [LIFT_AT + 18, LIFT_AT + 40], [0, 1], clamp));

  const card = (i: number) => {
    const shot = screenshots.length > 0 ? screenshots[i % screenshots.length] : undefined;
    return shot ? <Img src={shot} style={{ width: "100%", height: "100%", objectFit: "cover" }} /> : <PlaceholderScreen theme={theme} seed={i} />;
  };

  const planeW = COLS * (CARD_W + GAP);
  const planeH = ROWS * (CARD_H + GAP);

  return (
    <AbsoluteFill style={{ background: theme.background, fontFamily: family, overflow: "hidden", perspective: 2400 }}>
      <div
        style={{
          position: "absolute",
          left: 960 - planeW / 2,
          top: 540 - planeH / 2,
          width: planeW,
          height: planeH,
          display: "grid",
          gridTemplateColumns: `repeat(${COLS}, ${CARD_W}px)`,
          gap: GAP,
          opacity: enter,
          transform: `rotateX(${TILT_X}deg) rotateZ(${TILT_Z}deg) translate(${dx}px, ${dy}px) scale(${0.94 + 0.06 * enter})`,
        }}
      >
        {Array.from({ length: COLS * ROWS }, (_, i) => (
          <div key={i} style={{ position: "relative", width: CARD_W, height: CARD_H, borderRadius: 20, overflow: "hidden", border: `1px solid ${theme.border}`, boxShadow: `0 24px 48px -28px oklch(0 0 0 / 0.35)` }}>
            {card(i)}
          </div>
        ))}
      </div>

      <AbsoluteFill style={{ background: withAlpha(theme.background, 0.72 * lift) }} />

      {lift > 0 && (
        <AbsoluteFill style={{ alignItems: "center", justifyContent: "center", perspective: 2400 }}>
          <div
            style={{
              position: "relative",
              width: 1040,
              height: 650,
              marginTop: -70,
              borderRadius: 28,
              overflow: "hidden",
              border: `1px solid ${theme.border}`,
              boxShadow: `0 60px 120px -40px oklch(0 0 0 / 0.5)`,
              opacity: interpolate(lift, [0, 0.2], [0, 1], clamp),
              transform: `translateY(${(1 - lift) * 160}px) rotateX(${(1 - lift) * TILT_X}deg) rotateZ(${(1 - lift) * TILT_Z}deg) scale(${0.46 + 0.54 * lift})`,
            }}
          >
            {card(heroIndex)}
          </div>
          <div style={{ position: "absolute", top: 540 + 325 - 70 + 48, fontSize: 44, fontWeight: 600, letterSpacing: "-0.02em", color: theme.foreground, opacity: captionT, transform: `translateY(${(1 - captionT) * 14}px)` }}>
            {caption}
          </div>
        </AbsoluteFill>
      )}
    </AbsoluteFill>
  );
}
